<template><view class="page"><view class="card"><text class="heading">生产数据分析</text><text class="muted">{{farmName}} · 按实际生产记录统计</text><business-fields :fields="dateFields" v-model="range"/><view class="buttons"><button size="mini" @click="quick(false)">近30天</button><button size="mini" @click="quick(true)">本月</button><button size="mini" :disabled="busy" @click="load">查询</button><button size="mini" @click="openWorkspace('/production/analytics/reports')">生产报表</button></view></view><view class="notice">采收量统一为 kg；任务完成须验收通过。面积按地块去重，不能跨月份累加。未接入账务数据，不推算成本收益。</view><view v-if="error" class="error">{{error}}</view><view v-if="busy" class="card">正在统计…</view><template v-else-if="loaded"><view class="metrics"><view><text>{{total.quantity}}</text><text>期间采收 kg</text></view><view><text>{{total.tasks}}</text><text>排期任务</text></view><view><text>{{total.done}}</text><text>验收通过</text></view><view><text>{{total.rate}}</text><text>验收完成率</text></view></view><view class="card"><text class="heading">逐日趋势</text><view class="buttons"><button v-for="m in metricOptions" :key="m.value" size="mini" :class="{active:metric===m.value}" @click="metric=m.value;load()">{{m.label}}</button><button size="mini" @click="exportTrend">导出趋势</button></view><text v-if="!trend.length" class="muted">所选期间暂无记录</text><view v-for="point in trend" :key="point.bizDate" class="trend"><view class="row"><text>{{point.bizDate}}</text><text>{{point.metricValue==null?'缺测':point.metricValue+(metric==='YIELD'?' kg':'%')}}</text></view><view class="track"><view v-if="point.metricValue!=null" class="bar" :style="{width:width(point.metricValue)+'%'}"/></view></view></view><view class="card"><text class="heading">维度分析</text><view class="buttons"><button v-for="item in dimensions" :key="item.value" size="mini" :class="{active:dimension===item.value}" @click="dimension=item.value;load()">{{item.label}}</button><button size="mini" @click="exportDimension">导出分析</button></view><text v-if="!rows.length" class="muted">暂无数据</text><view v-for="r in rows" :key="r.name" class="record"><text class="heading">{{r.name}}</text><view class="row"><text>采收量</text><text>{{r.yieldQty ?? '—'}} kg</text></view><view class="row"><text>涉及地块面积</text><text>{{r.areaMu ?? '—'}} 亩</text></view><view class="row"><text>排期 / 验收通过</text><text>{{r.taskCount}} / {{r.doneCount}}</text></view><button size="mini" @click="openWorkspace('/production/harvests')">查看采收台账</button></view></view></template></view></template>
<script setup lang="ts">
import {ref,computed} from 'vue'
import {onShow,onHide,onPullDownRefresh} from '@dcloudio/uni-app'
import {call,date,type Row} from '@/api/native-business'
import {ensureWorkspaceSession,isProductionOps,openWorkspace} from '@/utils/workspace'
import {resolveCurrentFarm} from '@/utils/auth-helper'
import {contextGuard,csv,saveText} from '@/utils/business-files'
import BusinessFields from '@/components/business-fields/business-fields.vue'
const range=ref<Row>({}),farmId=ref(''),farmName=ref(''),dimension=ref('crop'),metric=ref('YIELD'),rows=ref<Row[]>([]),trend=ref<Row[]>([]),busy=ref(false),loaded=ref(false),error=ref('');let version=0
const dateFields=[date('startDate','开始日期',true),date('endDate','结束日期',true)]
const dimensions=[{value:'crop',label:'作物'},{value:'plot',label:'地块'},{value:'month',label:'月份'}],metricOptions=[{value:'YIELD',label:'采收量'},{value:'PASS_RATE',label:'检测合格率'}]
const day=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`
function dates(month=false){const end=new Date(),start=new Date();if(month)start.setDate(1);else start.setDate(start.getDate()-29);range.value={startDate:day(start),endDate:day(end)}}
function quick(month:boolean){dates(month);void load()}
const total=computed(()=>{const t=rows.value.reduce<{quantity:number;tasks:number;done:number}>((a,r)=>({quantity:a.quantity+Number(r.yieldQty||0),tasks:a.tasks+Number(r.taskCount||0),done:a.done+Number(r.doneCount||0)}),{quantity:0,tasks:0,done:0});return {...t,quantity:Number(t.quantity.toFixed(3)),rate:t.tasks?(t.done/t.tasks*100).toFixed(1)+'%':'—'}})
const maximum=computed(()=>metric.value==='PASS_RATE'?100:Math.max(1,...trend.value.filter(p=>p.metricValue!=null).map(p=>Number(p.metricValue))))
const width=(v:any)=>Math.max(0,Math.min(100,Number(v)/maximum.value*100))
async function load(){const run=++version;busy.value=true;loaded.value=false;error.value='';rows.value=[];trend.value=[];try{if(!await ensureWorkspaceSession())return;if(isProductionOps())throw new Error('请先切换到用户端');const farm=await resolveCurrentFarm();if(!farm)return;farmId.value=String(farm.farmId);farmName.value=farm.farmName||'';if(!range.value.startDate)dates();if(range.value.startDate>range.value.endDate)throw new Error('结束日期不能早于开始日期');const guard=contextGuard(),args={...range.value,farmId:farmId.value};const [a,b]=await Promise.all([call('/analytics/dimension','GET',undefined,{...args,dimension:dimension.value}),call('/analytics/trend','GET',undefined,{...args,metricCode:metric.value})]);guard();if(run!==version)return;if(!Array.isArray(a)||!Array.isArray(b))throw new Error('统计数据格式异常');rows.value=a;trend.value=b;loaded.value=true}catch(e:any){if(run===version)error.value=e.message}finally{if(run===version)busy.value=false;uni.stopPullDownRefresh()}}
async function exportDimension(){try{await saveText('生产维度分析.csv',csv(rows.value,[{key:'name',label:'维度'},{key:'yieldQty',label:'采收量kg'},{key:'areaMu',label:'涉及地块面积亩（不可跨月累加）'},{key:'taskCount',label:'排期任务数'},{key:'doneCount',label:'验收通过数'}]))}catch(e:any){error.value=e.message}}
async function exportTrend(){try{await saveText('生产逐日趋势.csv',csv(trend.value,[{key:'bizDate',label:'日期'},{key:'metricValue',label:metric.value==='YIELD'?'采收量kg':'检测合格率%'},{key:'metricCode',label:'指标'}]))}catch(e:any){error.value=e.message}}
onShow(()=>void load());onHide(()=>{version++;loaded.value=false;rows.value=[];trend.value=[]});onPullDownRefresh(()=>void load())
</script>
<style scoped>.page{padding:24rpx 24rpx calc(40rpx + env(safe-area-inset-bottom));background:#f4f6f2;min-height:100vh;box-sizing:border-box}.card{background:#fff;border-radius:18rpx;padding:26rpx;margin-bottom:24rpx}.heading{display:block;font-size:32rpx;font-weight:600;margin-bottom:18rpx}.muted,.notice{font-size:24rpx;color:#666666;line-height:1.7}.notice{padding:22rpx;background:#eaf2e6;margin-bottom:24rpx}.buttons{display:flex;flex-wrap:wrap;gap:14rpx;margin:20rpx 0}.buttons button{margin:0;min-height:84rpx;font-size:25rpx}.active{background:#126d43;color:#fff}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:16rpx;margin-bottom:24rpx}.metrics>view{background:#fff;padding:24rpx;border-radius:16rpx}.metrics text{display:block;font-size:24rpx;color:#687b6c}.metrics text:first-child{font-size:38rpx;color:#174b2e;font-weight:600;margin-bottom:12rpx}.row{display:flex;justify-content:space-between;gap:20rpx;font-size:26rpx;line-height:1.8}.trend{margin:24rpx 0}.track{height:14rpx;background:#edf1e9;border-radius:8rpx;margin-top:12rpx;overflow:hidden}.bar{height:100%;background:#27804f}.record{border-top:1rpx solid #e8eee3;padding-top:24rpx;margin-top:24rpx}.record button{margin:20rpx 0 0}.error{background:#fff0e8;color:#a43d28;padding:24rpx;margin-bottom:24rpx;font-size:26rpx}</style>
